const { useState, useRef, useEffect } = React;

// ===== 튜닝 상수 (한 곳에 모아 밸런스 조정을 쉽게) =====
const STAGE_W = 760;
const STAGE_H = 460;
const GROUND_H = 26;
const PLAYER_W = 40;
const PLAYER_H = 42;
const GRAVITY = 0.0017;       // 중력 가속도 (px/ms^2)
const JUMP_V = -0.8;          // 점프 초기 속도
const MOVE_SPEED = 0.33;      // 좌우 이동 속도
const BUBBLE = 36;            // 버블 지름
const BUBBLE_TRAVEL = 0.42;   // 버블이 날아가는 속도
const BUBBLE_RISE = 0.13;     // 버블이 떠오르는 속도
const BUBBLE_RANGE = 360;     // 버블이 날아가는 거리
const BUBBLE_LIFE = 5200;     // 빈 버블 수명(ms)
const CAPTURE_LIFE = 7000;    // 적을 가둔 버블의 안전장치 수명(보통은 위→아래 1왕복 후 바닥에서 부활)
const DEADZONE = 12;          // 조이스틱 데드존
const COMBO_WINDOW = 1500;    // 콤보 유지 시간(ms)
const SPAWN_INTERVAL = 1400;  // 적 등장 간격(ms)

const PLATFORMS = [
  { x: 0, y: STAGE_H - GROUND_H, w: STAGE_W, h: GROUND_H },
  { x: 70, y: 348, w: 210, h: 16 },
  { x: 480, y: 348, w: 210, h: 16 },
  { x: 290, y: 252, w: 180, h: 16 },
  { x: 48, y: 158, w: 180, h: 16 },
  { x: 532, y: 158, w: 180, h: 16 },
];

const ENEMY_KINDS = [
  { emoji: '👾', color: '#a78bfa' },
  { emoji: '👻', color: '#f0abfc' },
  { emoji: '🦠', color: '#fca5a5' },
];

const COMBO_LED = [
  [52, 211, 153], [250, 204, 21], [251, 146, 60], [248, 113, 113], [232, 121, 249],
];

// ===== 장식용 컴포넌트 =====
function Platform({ block }) {
  const isGround = block.w === STAGE_W;
  return (
    <div
      className="absolute"
      style={{
        left: block.x, top: block.y, width: block.w, height: block.h,
        borderRadius: isGround ? '14px 14px 0 0' : 999,
        background: 'linear-gradient(180deg,#5eead4 0%,#0d9488 70%,#0f766e 100%)',
        boxShadow: '0 5px 0 rgba(8,68,60,0.5), 0 8px 18px rgba(0,0,0,0.32), inset 0 2px 3px rgba(255,255,255,0.55)',
      }}
    >
      <div className="absolute inset-x-3 top-1 rounded-full" style={{ height: 3, background: 'rgba(255,255,255,0.5)' }} />
    </div>
  );
}

// 플레이어 캐릭터 (CSS만으로 그린 귀여운 공룡)
function PlayerSprite() {
  return (
    <div className="relative w-full h-full">
      <div className="absolute rounded-full" style={{ left: '50%', bottom: -4, width: 28, height: 8, transform: 'translateX(-50%)', background: 'rgba(0,0,0,0.28)', filter: 'blur(2px)' }} />
      {/* 꼬리: 기본 스프라이트가 '오른쪽'을 보도록 왼쪽(뒤쪽)에 둔다 → dir=1(오른쪽 이동) 시 자연스러움 */}
      <div className="absolute rounded-full" style={{ left: -7, top: 16, width: 17, height: 17, background: 'linear-gradient(180deg,#34d399,#15803d)', borderRadius: '60% 0 60% 60%' }} />
      <div className="absolute inset-0" style={{ borderRadius: '46% 46% 42% 42%', background: 'linear-gradient(165deg,#86efac 0%,#22c55e 55%,#15803d 100%)', boxShadow: 'inset 0 -5px 7px rgba(0,0,0,0.25), inset 0 3px 4px rgba(255,255,255,0.55), 0 3px 6px rgba(0,0,0,0.3)' }} />
      <div className="absolute rounded-full" style={{ left: '50%', bottom: 5, width: '54%', height: '40%', transform: 'translateX(-50%)', background: 'rgba(255,255,255,0.6)', borderRadius: '50%' }} />
      <div className="absolute rounded-full bg-white" style={{ width: 11, height: 11, left: 8, top: 9, boxShadow: 'inset 0 0 2px rgba(0,0,0,0.2)' }}>
        <div className="absolute rounded-full bg-slate-900" style={{ width: 5, height: 5, left: 4, top: 4 }} />
      </div>
      <div className="absolute rounded-full bg-white" style={{ width: 11, height: 11, right: 8, top: 9, boxShadow: 'inset 0 0 2px rgba(0,0,0,0.2)' }}>
        <div className="absolute rounded-full bg-slate-900" style={{ width: 5, height: 5, left: 2, top: 4 }} />
      </div>
      <div className="absolute" style={{ left: '50%', bottom: 10, width: 10, height: 5, transform: 'translateX(-50%)', borderBottom: '2px solid rgba(15,23,42,0.6)', borderRadius: '0 0 8px 8px' }} />
      <div className="absolute" style={{ left: 12, top: -3, width: 6, height: 9, background: '#16a34a', borderRadius: '60% 60% 0 0' }} />
      <div className="absolute" style={{ right: 12, top: -3, width: 6, height: 9, background: '#16a34a', borderRadius: '60% 60% 0 0' }} />
    </div>
  );
}

function App() {
  const stageElRef = useRef(null);
  const playerElRef = useRef(null);
  const fxLayerRef = useRef(null);          // 파티클·점수팝업을 직접 그리는 레이어
  const nodeMapRef = useRef(new Map());     // id -> DOM (버블/적 transform 직접 갱신)

  const playerRef = useRef(null);
  const joyRef = useRef({ x: 0, y: 0 });
  const shootRef = useRef(false);
  const bubblesRef = useRef([]);
  const enemiesRef = useRef([]);
  const fxRef = useRef([]);                  // {el, x, y, vx, vy, g, life, max, kind}
  const idRef = useRef(1);

  const comboRef = useRef(0);
  const comboExpireRef = useRef(0);
  const shakeRef = useRef(0);
  const waveRef = useRef(1);
  const toSpawnRef = useRef(0);
  const phaseRef = useRef('ready');          // 루프가 읽는 현재 상태(ready/playing/clear/over)

  const scoreRef = useRef(0);
  const livesRef = useRef(3);
  const lastHudRef = useRef(0);

  const [, bump] = useState(0);              // 엔티티 '집합'이 바뀔 때만 리렌더
  const [phase, setPhase] = useState('ready');
  const [hud, setHud] = useState({ score: 0, lives: 3, wave: 1, combo: 0 });
  const [best, setBest] = useState(() => Number(localStorage.getItem('bubble_best') || 0));
  const [banner, setBanner] = useState('');

  const freshPlayer = () => ({
    x: STAGE_W / 2 - PLAYER_W / 2,
    y: STAGE_H - GROUND_H - PLAYER_H,
    vy: 0, dir: 1, onGround: true,
    invincibleUntil: 0, landAt: 0, jumpAt: 0,
  });

  // ── MODI 입력: 조이스틱 → ref (매 프레임 최신값 사용) ──
  useEffect(() => {
    const offX = MODI.onValue('joystick', 1, 'x', (v) => { joyRef.current.x = v || 0; }, { pollMs: 24 });
    const offY = MODI.onValue('joystick', 1, 'y', (v) => { joyRef.current.y = v || 0; }, { pollMs: 24 });
    return () => { offX(); offY(); };
  }, []);

  // ── MODI 입력: 버튼 → 발사 / 화면 전환 ──
  const btn = useButton(1);
  useEffect(() => {
    if (!btn.clicked) return;
    if (phaseRef.current === 'playing') {
      shootRef.current = true;
    } else {
      startGame();
    }
  }, [btn.clicked]);

  // 키보드도 지원 (하드웨어 없이 테스트/시연용)
  useEffect(() => {
    const down = (e) => {
      if (e.key === 'ArrowLeft' || e.key === 'a') joyRef.current.x = -100;
      else if (e.key === 'ArrowRight' || e.key === 'd') joyRef.current.x = 100;
      else if (e.key === 'ArrowUp' || e.key === 'w') joyRef.current.y = 100;
      else if (e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        if (phaseRef.current === 'playing') shootRef.current = true;
        else startGame();
      }
    };
    const up = (e) => {
      if (['ArrowLeft', 'a', 'ArrowRight', 'd'].includes(e.key)) joyRef.current.x = 0;
      if (['ArrowUp', 'w'].includes(e.key)) joyRef.current.y = 0;
    };
    window.addEventListener('keydown', down);
    window.addEventListener('keyup', up);
    return () => { window.removeEventListener('keydown', down); window.removeEventListener('keyup', up); };
  }, []);

  const registerNode = (id, x, y) => (el) => {
    if (el) { nodeMapRef.current.set(id, el); el.style.transform = `translate3d(${x}px,${y}px,0)`; }
    else nodeMapRef.current.delete(id);
  };

  // ── 이펙트: 파티클을 fx 레이어에 직접 생성 (리렌더 없이 가볍게) ──
  const burst = (cx, cy, color, n) => {
    const layer = fxLayerRef.current;
    if (!layer) return;
    for (let i = 0; i < n; i++) {
      const el = document.createElement('div');
      const size = 5 + Math.random() * 6;
      el.style.cssText = `position:absolute;left:0;top:0;width:${size}px;height:${size}px;border-radius:50%;background:${color};box-shadow:0 0 8px ${color};will-change:transform,opacity;`;
      layer.appendChild(el);
      const ang = Math.random() * Math.PI * 2;
      const sp = 0.12 + Math.random() * 0.26;
      fxRef.current.push({ el, x: cx, y: cy, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp - 0.1, g: 0.0011, life: 520 + Math.random() * 240, max: 760, kind: 'dot' });
    }
  };

  const popText = (cx, cy, text, color) => {
    const layer = fxLayerRef.current;
    if (!layer) return;
    const el = document.createElement('div');
    el.textContent = text;
    el.style.cssText = `position:absolute;left:0;top:0;font-weight:800;font-size:18px;color:${color};text-shadow:0 2px 6px rgba(0,0,0,0.5);white-space:nowrap;will-change:transform,opacity;`;
    layer.appendChild(el);
    fxRef.current.push({ el, x: cx, y: cy, vx: 0, vy: -0.06, g: 0, life: 900, max: 900, kind: 'text' });
  };

  const beginWave = (w) => {
    waveRef.current = w;
    toSpawnRef.current = 3 + w;            // 웨이브가 오를수록 적이 많아짐
    setBanner(`WAVE ${w}`);
    MODI.led(1).setColor(56, 189, 248);
    setTimeout(() => MODI.led(1).off(), 400);
    setTimeout(() => setBanner(''), 1100);
  };

  const startGame = () => {
    enemiesRef.current = [];
    bubblesRef.current = [];
    fxRef.current.forEach((f) => f.el.remove());
    fxRef.current = [];
    nodeMapRef.current.clear();
    scoreRef.current = 0;
    livesRef.current = 3;
    comboRef.current = 0;
    shakeRef.current = 0;
    playerRef.current = freshPlayer();
    setHud({ score: 0, lives: 3, wave: 1, combo: 0 });
    phaseRef.current = 'playing';
    setPhase('playing');
    beginWave(1);
    bump((n) => n + 1);
  };

  // ── 메인 게임 루프 (requestAnimationFrame + 델타타임) ──
  useEffect(() => {
    playerRef.current = playerRef.current || freshPlayer();
    let raf;
    let last = performance.now();
    let spawnTimer = 0;
    let clearAt = 0;

    const landOn = (e, sz, prevY) => {
      if (e.vy < 0) return false;
      for (const b of PLATFORMS) {
        const footPrev = prevY + sz, footNow = e.y + sz;
        const withinX = e.x + sz > b.x + 4 && e.x < b.x + b.w - 4;
        if (withinX && footPrev <= b.y && footNow >= b.y) { e.y = b.y - sz; e.vy = 0; return true; }
      }
      return false;
    };

    const loop = (now) => {
      let dt = now - last;
      last = now;
      if (dt > 50) dt = 50;                 // 탭 비활성 등으로 dt가 튀는 것 방지
      const playing = phaseRef.current === 'playing';

      const player = playerRef.current;
      const joy = joyRef.current;
      let changed = false;

      if (playing) {
        // 이동 (데드존 적용)
        const jx = Math.abs(joy.x) < DEADZONE ? 0 : joy.x / 100;
        if (jx !== 0) {
          player.x += jx * MOVE_SPEED * dt;
          player.dir = jx > 0 ? 1 : -1;
          player.x = Math.max(0, Math.min(STAGE_W - PLAYER_W, player.x));
        }
        // 점프
        if (joy.y > 45 && player.onGround) {
          player.vy = JUMP_V; player.onGround = false; player.jumpAt = now;
          MODI.speaker(1).playTone(523, 30); setTimeout(() => MODI.speaker(1).stop(), 70);
        }
        // 중력 + 착지
        const prevY = player.y;
        player.vy += GRAVITY * dt;
        player.y += player.vy * dt;
        const wasAir = !player.onGround;
        player.onGround = landOn(player, PLAYER_H, prevY);
        if (player.onGround && wasAir) player.landAt = now;
        if (player.y > STAGE_H) { player.y = -PLAYER_H; player.vy = 0; }

        // 발사
        if (shootRef.current) {
          shootRef.current = false;
          bubblesRef.current.push({
            id: idRef.current++, x: player.x + PLAYER_W / 2 - BUBBLE / 2, y: player.y + 2,
            vx: player.dir * BUBBLE_TRAVEL, travelLeft: BUBBLE_RANGE, life: BUBBLE_LIFE, trapped: false, captured: null, bornAt: now,
          });
          MODI.speaker(1).playTone(700, 30); setTimeout(() => MODI.speaker(1).stop(), 90);
          changed = true;
        }
      }

      // 버블 이동
      const bubbles = bubblesRef.current;
      for (const b of bubbles) {
        if (b.travelLeft > 0) { const m = b.vx * dt; b.x += m; b.travelLeft -= Math.abs(m); }
        else if (b.trapped) {
          // 적을 가둔 버블: 위로 떠오르다가 천장에 닿으면 '한 번' 다시 내려온다.
          if (!b.falling) { b.y -= BUBBLE_RISE * dt; if (b.y <= 8) b.falling = true; }
          else b.y += BUBBLE_RISE * dt;
        } else {
          b.y -= BUBBLE_RISE * dt;   // 빈 버블은 위로 떠올라 사라진다
        }
        b.x = Math.max(0, Math.min(STAGE_W - BUBBLE, b.x));
        b.life -= dt;
        const el = nodeMapRef.current.get(b.id);
        if (el) {
          const wob = Math.sin(now / 240 + b.id) * 2;
          el.style.transform = `translate3d(${b.x}px,${b.y + wob}px,0)`;
        }
      }

      // 적 등장 (웨이브에 남은 만큼)
      if (playing) {
        spawnTimer += dt;
        const maxConcurrent = Math.min(3 + waveRef.current, 7);
        if (spawnTimer > SPAWN_INTERVAL && toSpawnRef.current > 0 && enemiesRef.current.length < maxConcurrent) {
          spawnTimer = 0; toSpawnRef.current -= 1;
          const fromLeft = Math.random() > 0.5;
          const kind = Math.floor(Math.random() * ENEMY_KINDS.length);
          enemiesRef.current.push({
            id: idRef.current++, x: fromLeft ? 6 : STAGE_W - BUBBLE - 6, y: 90 + Math.random() * 80,
            vy: 0, dir: fromLeft ? 1 : -1, onGround: false, kind,
            speed: 0.06 + waveRef.current * 0.012 + Math.random() * 0.02,
          });
          changed = true;
        }
      }

      // 적 이동 (중력 + 플랫폼 위 순찰)
      const enemies = enemiesRef.current;
      for (const e of enemies) {
        const prevY = e.y;
        e.vy += GRAVITY * dt;
        e.y += e.vy * dt;
        e.onGround = landOn(e, BUBBLE, prevY);
        if (e.y > STAGE_H + 40) { e.y = -BUBBLE; e.vy = 0; }
        e.x += e.dir * e.speed * dt;
        if (e.x < 4) { e.x = 4; e.dir = 1; }
        if (e.x > STAGE_W - BUBBLE - 4) { e.x = STAGE_W - BUBBLE - 4; e.dir = -1; }
        if (Math.random() < 0.003) e.dir *= -1;        // 가끔 방향 전환
        const el = nodeMapRef.current.get(e.id);
        if (el) { const wob = Math.sin(now / 180 + e.id) * 3; el.style.transform = `translate3d(${e.x}px,${e.y + wob}px,0)`; }
      }

      // 버블이 적을 가둠
      for (let bi = bubbles.length - 1; bi >= 0; bi--) {
        const b = bubbles[bi];
        if (b.trapped) continue;
        for (let ei = enemies.length - 1; ei >= 0; ei--) {
          const e = enemies[ei];
          const dx = (b.x + BUBBLE / 2) - (e.x + BUBBLE / 2);
          const dy = (b.y + BUBBLE / 2) - (e.y + BUBBLE / 2);
          if (dx * dx + dy * dy < BUBBLE * BUBBLE) {
            burst(e.x + BUBBLE / 2, e.y + BUBBLE / 2, ENEMY_KINDS[e.kind].color, 6);
            nodeMapRef.current.delete(e.id);
            enemies.splice(ei, 1);
            b.trapped = true; b.captured = e; b.travelLeft = 0; b.falling = false; b.life = CAPTURE_LIFE;
            MODI.speaker(1).playTone(880, 40); setTimeout(() => MODI.speaker(1).stop(), 90);
            changed = true;
            break;
          }
        }
      }

      // 플레이어가 갇힌 버블을 몸으로 터뜨림 → 점수 + 콤보
      for (let bi = bubbles.length - 1; bi >= 0; bi--) {
        const b = bubbles[bi];
        if (b.trapped && playing) {
          const pdx = (player.x + PLAYER_W / 2) - (b.x + BUBBLE / 2);
          const pdy = (player.y + PLAYER_H / 2) - (b.y + BUBBLE / 2);
          if (pdx * pdx + pdy * pdy < ((PLAYER_W + BUBBLE) / 2) * ((PLAYER_W + BUBBLE) / 2) * 0.6) {
            comboRef.current = now < comboExpireRef.current ? comboRef.current + 1 : 1;
            comboExpireRef.current = now + COMBO_WINDOW;
            const combo = comboRef.current;
            const gained = 100 * combo;
            scoreRef.current += gained;
            const cx = b.x + BUBBLE / 2, cy = b.y + BUBBLE / 2;
            burst(cx, cy, '#fde047', 12);
            popText(cx - 14, cy - 10, `+${gained}`, '#fde047');
            if (combo >= 2) popText(cx - 24, cy - 32, `COMBO x${combo}`, '#fb923c');
            shakeRef.current = Math.min(10, 4 + combo);
            const c = COMBO_LED[Math.min(combo - 1, COMBO_LED.length - 1)];
            MODI.led(1).setColor(c[0], c[1], c[2]); setTimeout(() => MODI.led(1).off(), 220);
            MODI.speaker(1).playTone(900 + combo * 120, 50); setTimeout(() => MODI.speaker(1).stop(), 140);
            nodeMapRef.current.delete(b.id); bubbles.splice(bi, 1);
            changed = true;
            continue;
          }
        }
        // 가둔 버블: 내려오기를 끝내면(바닥 근처) — 또는 안전장치 수명 초과 시 — 적이 부활.
        //            (위로 올라갔다가 한 번 내려오는 동안 못 터뜨리면 풀려난다)
        const reviveNow = b.trapped && b.captured &&
          ((b.falling && b.y >= STAGE_H - GROUND_H - BUBBLE) || b.life <= 0);
        // 빈 버블: 수명이 다하거나 화면 위로 빠져나가면 사라짐
        const emptyGone = !b.trapped && (b.life <= 0 || b.y < -BUBBLE);
        if (reviveNow || emptyGone) {
          if (reviveNow) {
            enemies.push({
              id: idRef.current++, x: Math.max(4, Math.min(STAGE_W - BUBBLE - 4, b.x)),
              y: Math.max(70, Math.min(STAGE_H - GROUND_H - BUBBLE, b.y)), vy: 0,
              dir: Math.random() > 0.5 ? 1 : -1, onGround: false, kind: b.captured.kind, speed: b.captured.speed,
            });
            MODI.speaker(1).playTone(300, 50); setTimeout(() => MODI.speaker(1).stop(), 120);
          } else {
            burst(b.x + BUBBLE / 2, b.y + BUBBLE / 2, 'rgba(165,243,252,0.9)', 5);
          }
          nodeMapRef.current.delete(b.id); bubbles.splice(bi, 1);
          changed = true;
        }
      }

      // 콤보 만료
      if (comboRef.current > 0 && now > comboExpireRef.current) comboRef.current = 0;

      // 플레이어 vs 풀려난 적 (목숨 감소)
      if (playing && now > player.invincibleUntil) {
        for (const e of enemies) {
          const hx = (player.x + PLAYER_W / 2) - (e.x + BUBBLE / 2);
          const hy = (player.y + PLAYER_H / 2) - (e.y + BUBBLE / 2);
          if (hx * hx + hy * hy < 30 * 30) {
            livesRef.current = Math.max(0, livesRef.current - 1);
            player.invincibleUntil = now + 1600;
            player.x = STAGE_W / 2 - PLAYER_W / 2; player.y = STAGE_H - GROUND_H - PLAYER_H; player.vy = 0;
            comboRef.current = 0;
            shakeRef.current = 14;
            burst(STAGE_W / 2, player.y, '#f87171', 14);
            MODI.led(1).setColor(220, 30, 30); setTimeout(() => MODI.led(1).off(), 350);
            MODI.speaker(1).playTone(180, 120); setTimeout(() => MODI.speaker(1).stop(), 260);
            changed = true;
            if (livesRef.current <= 0) {
              phaseRef.current = 'over'; setPhase('over');
              const b = Math.max(scoreRef.current, Number(localStorage.getItem('bubble_best') || 0));
              localStorage.setItem('bubble_best', String(b)); setBest(b);
            }
            break;
          }
        }
      }

      // 웨이브 클리어 판정 (남은 등장·적·가둔버블이 모두 없을 때)
      if (playing) {
        const noTrapped = !bubbles.some((b) => b.captured);
        if (toSpawnRef.current === 0 && enemies.length === 0 && noTrapped) {
          if (clearAt === 0) clearAt = now + 600;
          else if (now > clearAt) { clearAt = 0; scoreRef.current += 500; popText(STAGE_W / 2 - 40, STAGE_H / 2, '+500', '#5eead4'); beginWave(waveRef.current + 1); changed = true; }
        } else clearAt = 0;
      }

      // 파티클·점수팝업 갱신 (직접 DOM)
      const fx = fxRef.current;
      for (let i = fx.length - 1; i >= 0; i--) {
        const f = fx[i];
        f.life -= dt;
        if (f.life <= 0) { f.el.remove(); fx.splice(i, 1); continue; }
        f.vy += f.g * dt; f.x += f.vx * dt; f.y += f.vy * dt;
        const a = Math.max(0, f.life / f.max);
        f.el.style.opacity = a;
        f.el.style.transform = `translate3d(${f.x}px,${f.y}px,0)${f.kind === 'text' ? ` scale(${0.8 + a * 0.4})` : ''}`;
      }

      // 화면 흔들림
      if (stageElRef.current) {
        let sx = 0, sy = 0;
        if (shakeRef.current > 0.2) {
          shakeRef.current *= 0.86;
          sx = (Math.random() - 0.5) * shakeRef.current * 2;
          sy = (Math.random() - 0.5) * shakeRef.current * 2;
        } else shakeRef.current = 0;
        stageElRef.current.style.transform = `translate(${sx}px,${sy}px)`;
      }

      // 플레이어 렌더 (스쿼시·스트레치 + 깜빡임)
      if (playerElRef.current) {
        let sy = 1, sxq = 1;
        const sinceLand = now - player.landAt, sinceJump = now - player.jumpAt;
        if (sinceLand < 130) { const k = 1 - sinceLand / 130; sy = 1 - 0.22 * k; sxq = 1 + 0.22 * k; }
        else if (!player.onGround && sinceJump < 200) { const k = 1 - sinceJump / 200; sy = 1 + 0.16 * k; sxq = 1 - 0.16 * k; }
        const blink = now < player.invincibleUntil && Math.floor(now / 110) % 2 === 0;
        playerElRef.current.style.opacity = blink ? '0.35' : '1';
        playerElRef.current.style.transform = `translate3d(${player.x}px,${player.y}px,0) scaleX(${player.dir * sxq}) scaleY(${sy})`;
      }

      // HUD는 자주 안 바꿈 (리렌더 절약)
      if (now - lastHudRef.current > 120) {
        lastHudRef.current = now;
        setHud((h) => {
          const s = scoreRef.current, l = livesRef.current, w = waveRef.current, c = comboRef.current;
          if (h.score === s && h.lives === l && h.wave === w && h.combo === c) return h;
          return { score: s, lives: l, wave: w, combo: c };
        });
      }

      if (changed) bump((n) => n + 1);
      raf = requestAnimationFrame(loop);
    };

    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);

  return (
    <div className="min-h-full flex flex-col items-center justify-center gap-5 p-6" style={{ background: 'radial-gradient(circle at 50% -10%,#1e3a8a 0%,#0f172a 65%,#020617 100%)' }}>
      <style>{`
        @keyframes floatUp { from{transform:translateY(0)} to{transform:translateY(-26px)} }
        @keyframes bannerPop { 0%{transform:scale(0.6);opacity:0} 25%{transform:scale(1.05);opacity:1} 75%{transform:scale(1);opacity:1} 100%{transform:scale(1.1);opacity:0} }
        @keyframes drift { from{transform:translateY(0)} to{transform:translateY(-540px)} }
      `}</style>

      {/* HUD */}
      <div className="flex items-center justify-between w-full max-w-[760px] px-6 py-3 rounded-2xl text-white" style={{ background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.12)', backdropFilter: 'blur(8px)', boxShadow: '0 8px 24px rgba(0,0,0,0.3)' }}>
        <h1 className="text-2xl font-extrabold tracking-tight flex items-center gap-2">
          <span className="text-3xl">🫧</span>
          <span className="bg-gradient-to-r from-cyan-300 to-emerald-300 bg-clip-text text-transparent">보글보글</span>
        </h1>
        <div className="flex items-center gap-5">
          <div className="flex flex-col items-center leading-none">
            <span className="text-[10px] font-semibold tracking-widest text-cyan-300/70">WAVE</span>
            <span className="text-lg font-extrabold text-cyan-200 tabular-nums">{hud.wave}</span>
          </div>
          <div className="flex flex-col items-end leading-none">
            <span className="text-[10px] font-semibold tracking-widest text-cyan-300/70">SCORE</span>
            <span className="text-xl font-extrabold text-amber-300 tabular-nums">{hud.score}</span>
          </div>
          <span className="text-lg">{'❤️'.repeat(Math.max(0, hud.lives))}</span>
        </div>
      </div>

      {/* 게임 무대 (흔들림은 stageEl에만 적용) */}
      <div ref={stageElRef} style={{ width: STAGE_W, height: STAGE_H, willChange: 'transform' }}>
        <div className="relative overflow-hidden rounded-3xl w-full h-full" style={{ background: 'linear-gradient(180deg,#0c4a6e 0%,#0e7490 45%,#155e75 100%)', border: '3px solid rgba(255,255,255,0.14)', boxShadow: '0 24px 60px rgba(0,0,0,0.5), inset 0 0 90px rgba(8,47,73,0.55)' }}>
          {/* 떠오르는 배경 거품 */}
          <div className="absolute inset-0 pointer-events-none">
            {[12, 28, 46, 63, 78, 90].map((lx, i) => (
              <div key={i} className="absolute rounded-full" style={{ left: `${lx}%`, bottom: -30, width: 10 + (i % 3) * 8, height: 10 + (i % 3) * 8, background: 'radial-gradient(circle at 35% 30%, rgba(255,255,255,0.5), rgba(125,211,252,0.12))', animation: `drift ${7 + i}s linear ${i * 1.2}s infinite` }} />
            ))}
          </div>
          <div className="absolute inset-x-0 top-0 h-28 pointer-events-none" style={{ background: 'linear-gradient(180deg, rgba(125,211,252,0.22), transparent)' }} />

          {PLATFORMS.map((b, i) => <Platform key={i} block={b} />)}

          {enemiesRef.current.map((e) => (
            <div key={e.id} ref={registerNode(e.id, e.x, e.y)} className="absolute flex items-center justify-center" style={{ left: 0, top: 0, width: BUBBLE, height: BUBBLE, fontSize: 26, willChange: 'transform', filter: `drop-shadow(0 2px 4px rgba(0,0,0,0.4))` }}>
              {ENEMY_KINDS[e.kind].emoji}
            </div>
          ))}

          {bubblesRef.current.map((b) => (
            <div key={b.id} ref={registerNode(b.id, b.x, b.y)} className="absolute rounded-full flex items-center justify-center" style={{
              left: 0, top: 0, width: BUBBLE, height: BUBBLE, willChange: 'transform',
              background: b.trapped ? 'radial-gradient(circle at 32% 28%, rgba(255,255,255,0.95) 0%, rgba(253,224,71,0.5) 45%, rgba(251,191,36,0.22) 100%)' : 'radial-gradient(circle at 32% 28%, rgba(255,255,255,0.95) 0%, rgba(165,243,252,0.5) 45%, rgba(56,189,248,0.18) 100%)',
              border: b.trapped ? '2px solid rgba(253,224,71,0.85)' : '2px solid rgba(255,255,255,0.6)',
              boxShadow: b.trapped ? '0 0 16px rgba(251,191,36,0.6), inset 0 0 8px rgba(255,255,255,0.6)' : '0 0 12px rgba(125,211,252,0.5), inset 0 0 8px rgba(255,255,255,0.6)',
            }}>
              {b.trapped && b.captured && <span style={{ fontSize: 18, opacity: 0.92 }}>{ENEMY_KINDS[b.captured.kind].emoji}</span>}
            </div>
          ))}

          <div ref={playerElRef} className="absolute" style={{ left: 0, top: 0, width: PLAYER_W, height: PLAYER_H, willChange: 'transform' }}>
            <PlayerSprite />
          </div>

          {/* 파티클·점수팝업 레이어 (JS가 직접 그림) */}
          <div ref={fxLayerRef} className="absolute inset-0 pointer-events-none" />

          {/* 웨이브 배너 */}
          {banner && (
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <span className="text-5xl font-black text-white tracking-tight" style={{ textShadow: '0 4px 14px rgba(0,0,0,0.6)', animation: 'bannerPop 1.1s ease forwards' }}>{banner}</span>
            </div>
          )}

          {/* 시작 화면 */}
          {phase === 'ready' && (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-4" style={{ background: 'rgba(2,6,23,0.7)', backdropFilter: 'blur(3px)' }}>
              <p className="text-6xl">🫧</p>
              <p className="text-4xl font-black text-white tracking-tight">보글보글</p>
              <p className="text-cyan-200 text-center leading-relaxed text-sm">조이스틱 <b>좌우</b>로 이동 · <b>위로</b> 점프 · <b>버튼</b>으로 버블 발사<br/>적을 버블에 가두고 <b>몸으로 터뜨려</b> 처치! 연속으로 터뜨리면 <b>콤보</b> 보너스</p>
              {best > 0 && <p className="text-amber-300/90 text-sm">최고 점수 <b>{best}</b></p>}
              <button className="mt-1 px-8 py-3 rounded-2xl text-white font-bold transition-transform hover:scale-105" style={{ background: 'linear-gradient(180deg,#34d399,#0d9488)', boxShadow: '0 6px 18px rgba(13,148,136,0.5)' }} onClick={startGame}>
                버튼(또는 클릭)으로 시작 ▶
              </button>
            </div>
          )}

          {/* 게임 오버 */}
          {phase === 'over' && (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-4" style={{ background: 'rgba(2,6,23,0.8)', backdropFilter: 'blur(4px)' }}>
              <p className="text-5xl">💥</p>
              <p className="text-4xl font-black tracking-tight text-white">GAME OVER</p>
              <p className="text-lg text-cyan-200">점수 <span className="font-bold text-amber-300">{hud.score}</span> · WAVE <span className="font-bold text-cyan-200">{hud.wave}</span></p>
              <p className="text-amber-300/90 text-sm">최고 점수 <b>{best}</b></p>
              <button className="mt-1 px-8 py-3 rounded-2xl text-white font-bold transition-transform hover:scale-105" style={{ background: 'linear-gradient(180deg,#34d399,#0d9488)', boxShadow: '0 6px 18px rgba(13,148,136,0.5)' }} onClick={startGame}>
                다시 시작
              </button>
            </div>
          )}
        </div>
      </div>

      <p className="text-sm text-slate-300/70">조이스틱 좌우: 이동 · 위로: 점프 · 버튼: 버블 발사 — 갇힌 적을 몸으로 터뜨려 처치!</p>
    </div>
  );
}

export default App;
